import{_ as o,o as a,c as r,a5 as t}from"./chunks/framework.CXroN2RO.js";const s="/study/images/browser/audio-doppler-wavefronts.svg",d="/study/images/browser/audio-doppler-speed.svg",b=JSON.parse('{"title":"Web Audioでドップラー効果を再現する","description":"","frontmatter":{"title":"Web Audioでドップラー効果を再現する","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"動く音源から波の山が届く間隔を求め、近づくと音が高く、遠ざかると低く聞こえる変化をWeb Audioの再生速度で再現する。","aliases":["Web Audio API","ドップラー効果","Doppler effect","視線方向の速度","音速","周波数","AudioBufferSourceNode","playbackRate"],"verification":"OpenStax University Physicsの移動音源の式とW3C Web Audio APIのAudioBufferSourceNodeおよびPannerNodeの仕様に照合（2026-11-06）"}},"headers":[],"relativePath":"browser/audio-doppler.md","filePath":"browser/audio-doppler.md"}'),i={name:"browser/audio-doppler.md"};function p(n,e,c,l,u,f){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="web-audioでドップラー効果を再現する" tabindex="-1">Web Audioでドップラー効果を再現する <a class="header-anchor" href="#web-audioでドップラー効果を再現する" aria-label="Permalink to &quot;Web Audioでドップラー効果を再現する&quot;">​</a></h1><p>車が一定の音を出しながら近づくと高く聞こえ、遠ざかると低く聞こえます。音源が同じ間隔で波を出していても、動いている間は波を出す位置がずれ、聞き手に波が届く間隔が変わります。この変化が<strong>ドップラー効果</strong>です。ここでは風のない空気中で聞き手を固定し、音源が音速より遅い速さで動く場合を扱います。<a href="https://openstax.org/books/university-physics-volume-1/pages/17-7-the-doppler-effect" target="_blank" rel="noreferrer">OpenStaxのドップラー効果</a></p><h2 id="波が届く間隔から周波数を求める" tabindex="-1">波が届く間隔から周波数を求める <a class="header-anchor" href="#波が届く間隔から周波数を求める" aria-label="Permalink to &quot;波が届く間隔から周波数を求める&quot;">​</a></h2><p>音源が周波数 <code>f</code> で鳴ると、波の山を <code>T = 1 / f</code> 秒ごとに出します。波面は山がある場所をつないだ面です。静止した空気では、どの波面も出たときの音源の位置を中心として音速 <code>c</code> で広がります。動く音源から出た波面は、山を出した位置が一つずつ異なります。進行方向では波面どうしが近づき、後ろでは間隔が広がります。<a href="https://openstax.org/books/university-physics-volume-1/pages/17-7-the-doppler-effect" target="_blank" rel="noreferrer">OpenStaxの移動音源の波面</a></p><figure class="study-figure"><img src="'+s+`" alt="右へ進む音源を上から見る。各波面は発生時の音源の位置を中心とし、古い波面ほど大きい。右側の静止した聞き手に向かう波面は間隔が狭く、左側の聞き手に向かう波面は間隔が広い。" width="760" height="416" loading="lazy"><figcaption>丸は同じ時刻に見た複数の波面です。間隔の違いが見えるよう、図では音源の移動を大きく描いています。<a href="/study/images/browser/audio-doppler-wavefronts.svg" target="_blank" rel="noopener noreferrer">波面の図を拡大</a></figcaption></figure><p>音源と聞き手を結ぶ直線上で、音源が聞き手に向かう速度を正の <code>v</code> とします。音源が次の山を出すまでの <code>T</code> 秒に、聞き手までの距離は <code>v × T</code> だけ縮まります。次の山が出るのは <code>T</code> 秒後ですが、届くまでにかかる時間は <code>v × T / c</code> 秒短くなります。聞き手に届く間隔を <code>T&#39;</code>、聞こえる周波数を <code>f&#39;</code> とすると、次の式になります。遠ざかるときは <code>v</code> が負になり、届く間隔が延びます。<a href="https://openstax.org/books/university-physics-volume-1/pages/17-7-the-doppler-effect" target="_blank" rel="noreferrer">OpenStaxの移動音源の式</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>T&#39; = T − v × T / c = T × (1 − v / c)</span></span>
<span class="line"><span>f&#39; = 1 / T&#39; = f × c / (c − v)</span></span></code></pre></div><p>実践と同じく音速を343 m/s、音源の周波数を440 Hzとします。音源が40 m/sで近づくと約498.09 Hz、同じ速さで遠ざかると約394.05 Hzです。止まっていれば440 Hzのままです。</p><figure class="study-figure"><img src="`+d+'" alt="音速343 m/s、音源440 Hzでの理論値。聞き手に向かう速度がマイナス40 m/sでは394.05 Hz、ゼロでは440 Hz、プラス40 m/sでは498.09 Hzになる。" width="760" height="416" loading="lazy"><figcaption>横軸は聞き手に向かう速度です。左側は遠ざかる動き、右側は近づく動きを表します。<a href="/study/images/browser/audio-doppler-speed.svg" target="_blank" rel="noopener noreferrer">速度と周波数の図を拡大</a></figcaption></figure><h2 id="ゲーム内の速度を再生速度に反映する" tabindex="-1">ゲーム内の速度を再生速度に反映する <a class="header-anchor" href="#ゲーム内の速度を再生速度に反映する" aria-label="Permalink to &quot;ゲーム内の速度を再生速度に反映する&quot;">​</a></h2><p>車が聞き手の前を横切る場面では、車の速度のうち、聞き手に向かう成分を使います。音源から聞き手に向かう単位ベクトルと音源の速度ベクトルの内積を取ると、この成分を求められます。進路上で聞き手に最も近い位置では、音源の速度はその方向と直交し、成分はゼロです。そこを過ぎると成分が負になります。ゲームでは音が出た時刻と届く時刻の差を省略し、そのときの位置と速度から周波数の変化を近似できます。<a href="https://openstax.org/books/physics/pages/14-3-doppler-effect-and-sonic-booms" target="_blank" rel="noreferrer">OpenStaxの進行方向と速度成分</a></p><p>Web Audioでは、<code>AudioBufferSourceNode.playbackRate</code> に周波数の比 <code>f&#39; / f</code> を渡します。1より大きいと元のサンプルを速く読み進め、1より小さいとゆっくり読み進めます。有限の音声素材を最後まで再生する場合は、音の高さと再生時間が一緒に変わります。エンジン音のループを鳴らす場合は、移動に合わせてこの値を更新できます。<a href="https://www.w3.org/TR/webaudio/#AudioBufferSourceNode" target="_blank" rel="noreferrer">W3C Web Audio APIのAudioBufferSourceNode</a></p><p><code>PannerNode</code> は聞き手から見た方向と距離に応じて左右の出力を作ります。Web Audioでドップラー効果を加える場合は、音源側で再生速度を計算し、位置や向きはパンニングに渡します。例えば聞き手がその場で向きを変えると左右の定位は変わりますが、音源との位置関係から求める速度成分は同じです。<a href="https://www.w3.org/TR/webaudio/#PannerNode" target="_blank" rel="noreferrer">W3C Web Audio APIのPannerNode</a> · <a href="/study/browser/audio-spatial-panning.html">Web Audioの音の定位と距離減衰</a></p><h2 id="波形と音の高さを比べる" tabindex="-1">波形と音の高さを比べる <a class="header-anchor" href="#波形と音の高さを比べる" aria-label="Permalink to &quot;波形と音の高さを比べる&quot;">​</a></h2><p>実践では、440 Hzの音に対して音源の進む向きと速さを選び、一定の再生速度を使って波形を作ります。近づく場合と遠ざかる場合を同じ時間幅で表示すると、波の山の間隔が短くなるほど周波数が高いことを確かめられます。<a href="/study/practice/browser/audio-doppler-observation.html">ドップラー効果の実践</a></p>',15)])])}const g=o(i,[["render",p]]);export{b as __pageData,g as default};
